package com.bank.distinct.service;

import java.util.HashMap;
import java.util.Map;
import java.util.PriorityQueue;
import java.util.logging.Logger;

// Maximizes distinct codes after up to K removals.
public class DistinctService {
    private static final Logger log = Logger.getLogger(DistinctService.class.getName());

    public int maxDistinct(int[] codes, int k) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (int c : codes) freq.merge(c, 1, Integer::sum);
        PriorityQueue<Integer> minHeap = new PriorityQueue<>(); // surplus counts (>1)
        int distinct = 0;
        for (int count : freq.values()) {
            if (count == 1) distinct++;       // already distinct, free
            else minHeap.offer(count);        // needs count-1 removals to become distinct
        }
        while (k > 0 && !minHeap.isEmpty()) {
            int count = minHeap.poll();        // smallest surplus first
            int needed = count - 1;
            if (k >= needed) { k -= needed; distinct++; }
            else break;                        // cannot fully convert any further
        }
        final int result = distinct;
        log.info(() -> "Maximum distinct codes = " + result);
        return result;
    }
}
