package com.bank.distinct;

import com.bank.distinct.service.DistinctService;
import java.util.logging.Logger;

public class DistinctReportApplication {
    private static final Logger log = Logger.getLogger(DistinctReportApplication.class.getName());

    public static void main(String[] args) {
        DistinctService service = new DistinctService();
        int[] codes = {10, 10, 10, 20, 20, 30}; // 30 free; 20 needs 1; 10 needs 2
        log.info("Max distinct after 2 removals: " + service.maxDistinct(codes, 2));
    }
}
